package com.taller.gestion.domain;
import jakarta.persistence.*; import java.util.*; import java.time.*;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(unique=true,nullable=false) private String email; @Column(nullable=false) private String passwordHash; @Enumerated(EnumType.STRING) @ElementCollection(fetch=FetchType.EAGER) @CollectionTable(name="user_roles") private Set<Role> roles=new HashSet<>(); private String recoveryToken; private LocalDateTime recoveryExpiresAt; public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public Set<Role> getRoles(){return roles;} public void setRoles(Set<Role> v){roles=v;} public String getRecoveryToken(){return recoveryToken;} public void setRecoveryToken(String t){recoveryToken=t;} public LocalDateTime getRecoveryExpiresAt(){return recoveryExpiresAt;} public void setRecoveryExpiresAt(LocalDateTime v){recoveryExpiresAt=v;} }
